import os
import json
from pathlib import Path

def load_configs():
    """Load all JSON config files from the configured directory."""
    config_dir = os.getenv('CONFIG_PATH', '/etc/myapp/config')
    configs = {}

    # Read all files in the directory
    for filename in os.listdir(config_dir):
        filepath = os.path.join(config_dir, filename)

        # Skip directories
        if os.path.isdir(filepath):
            continue

        try:
            with open(filepath, 'r') as f:
                # Load JSON files
                if filename.endswith('.json'):
                    configs[filename] = json.load(f)
                # Load other files as raw text
                else:
                    configs[filename] = f.read()
        except (IOError, json.JSONDecodeError) as e:
            print(f"Warning: Could not load {filename}: {e}")

    return configs

if __name__ == '__main__':
    all_configs = load_configs()
    for name, content in all_configs.items():
        print(f"Loaded: {name}")
